    },
    {
      "factor": "Hedged Language",
      "polarity": -1,
      "reason_headline": "Ambiguous Profit Estimates",
      "reason_detailed": "The estimated profit of $50,000 to $75,000 in 3 months is presented as a range, which may indicate a lack of confidence in the prediction or an attempt to hedge against potential losses."
    },
    {
      "factor": "Insider Information",
      "polarity": -1,
      "reason_headline": "Potential for Insider Information",
      "reason_detailed": "The message from Sally@whitestone.com mentioning a surprise merger announcement for Linear Group raises concerns about the potential use of insider information, which could be a serious compliance violation."
    },
    {
      "factor": "Risk Assessment",
      "polarity": -1,
      "reason_headline": "Inadequate Risk Assessment",
      "reason_detailed": "The risk level is described as 'Medium', but the justification for this assessment is not provided, making it difficult to evaluate the adequacy of the risk management process."
    }
  ],
  "score": 20,
